arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: <TOKEN>' -d '{"query":"{ __type(name: \"Mutation\") { fields { name args { name type { name ofType { name } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__type']['fields']:
    for a in f['args']:
        t = a['type']['name'] or (a['type']['ofType'] or {}).get('name') or ''
        if 'Attachment' in t:
            print(f['name'], a['name'], t)
"

